/** Original guided derivations. Source links are supplementary readings, not copied chapters. */
export type StudyDepth={minutes:number;concept:string;cases:{title:string;steps:string[]}[];questions:{prompt:string;hint:string;answer:string}[];resources:string[];flow?:string[];caption?:string;code?:string;trace?:{headers:string[];rows:string[][]}};
const d=(concept:string,cases:StudyDepth['cases'],questions:StudyDepth['questions'],resources:string[]=[],minutes=45):StudyDepth=>({concept,cases,questions,resources,minutes});
export const studyDepth:Record<string,StudyDepth>={
 'finite-state-machines':d(
 '### Derive memory from distinguishable histories\nTwo histories need different states when some future input can make their outputs differ. For a 1011 detector, remember only the longest suffix that is also a proper prefix of 1011: empty, 1, 10 or 101. Extra history is unnecessary. Build every transition by appending the next bit and finding that suffix again. This construction explains fallback edges rather than guessing them.\n\n### Moore versus Mealy is an observation contract\nA Mealy match is a function of the pre-edge state and current input. For this lesson it is sampled at the edge consuming the last 1. A Moore version introduces a matched state and derives its level from that state; the level becomes visible after the consuming edge. A registered Mealy pulse also appears after an edge, so state-count and latency claims must name the chosen output register and sampling point. Reset clears history; specify whether output is suppressed while reset is active.',
 [{title:'Derive all fallback edges for 1011',steps:['In S1, append 1: history ends in 11. The longest useful suffix is 1, so stay in S1; do not reset.','In S10, append 0: 100 has no nonempty suffix that is a prefix of 1011, so go to S0.','In S101, append 0: 1010 ends in 10, so go to S10. Append 1 instead: report a match and retain suffix 1 in S1.','Check all four states for both input values against the transition table. This is eight obligations, not just the three forward arrows.']},{title:'Trace overlapping and reset sequences',steps:['Start S0 and consume 1011011. Post-edge states are S1, S10, S101, S1, S10, S101, S1. Matches occur on bits 4 and 7.','For a non-overlapping detector, force S0 after a match. The second match in that same stream disappears because bit 4 cannot start a new candidate.','Insert reset after the first three bits of 1011. The final 1 now starts a new candidate; it must not complete the pre-reset history.','Use an independent sliding four-bit window in a testbench. Clear the window on reset and compare at the exact documented match sampling point.']}],
 [{prompt:'Without RTL, derive the state trace and match positions for 1101011 with overlap enabled.',hint:'After every bit retain the longest suffix among empty, 1, 10 and 101.',answer:'Post-edge states: S1, S1, S10, S101, S10, S101, S1. Only bit 7 completes 1011. The 0 at bit 5 takes S101 back to S10.'},{prompt:'Design a Moore detector with a MATCH state. What is its transition on 0 after a match?',hint:'The matched history ends in 1011; now append 0 and retain a useful suffix.',answer:'10110 ends in 10, so MATCH on 0 goes to S10; on 1 it goes to S1. MATCH drives the Moore output high. Describe the post-edge level and reset behavior before comparing it to the Mealy contract.'}],[],60),
 'assignment-semantics':d(
 '### Work through the scheduling boundary\nFor nonblocking assignments the right-hand expressions are evaluated when the process executes, while updates are scheduled for the NBA region. Two registers in a pipeline therefore both read pre-update values at an edge. Blocking assignment updates its target immediately within the executing process; later statements in that process see the new value. Separate active-region processes have no general execution order. A style rule helps, but predicting values from the scheduling model is the actual reasoning skill.\n\nTestbench sampling has its own contract. A sample taken immediately on a rising edge may precede NBA updates. Use the simulator’s supported settled/read-only phase or a deliberate clocking-block sampling policy. Do not repair a race by inserting arbitrary zero delays and assuming every simulator will agree.',
 [{title:'Two pipeline registers, two possible programs',steps:['Before the edge let a=2, b=7 and in=9. With a<=in; b<=a, evaluate both RHS values as 9 and 2.','After NBA, a=9 and b=2. The second stage contains the previous first-stage value.','With a=in; b=a in one process, a becomes 9 before b is evaluated, so b becomes 9 too. The intended pipeline latency collapses.']},{title:'Find a misleading checker',steps:['A DUT schedules q<=d at the edge; a testbench also wakes at that edge and compares q to d immediately.','The comparison may see old q. First state whether the requirement concerns pre-edge q or the settled result.','For a settled-result checker, wait for the supported read-only phase, then compare q against the expected sampled d. Preserve the sample separately if d can change later.']}],
 [{prompt:'Initially a=0,b=0. Inputs at three edges are 5,8,3. Predict (a,b) after each NBA update.',hint:'b gets old a.',answer:'(5,0), (8,5), (3,8). Reset or enable would change the recurrence and must be included explicitly.'},{prompt:'Why is replacing <= with = in two separate clocked processes especially risky?',hint:'Consider which process happens first.',answer:'The consumer can observe either the old or newly assigned producer value depending on active-region ordering. NBA updates preserve old-value sampling across the clocked processes.'}],['sv-process']),
 'combinational-rtl':d(
 '### Assignment completeness is a path property\nA combinational process must define every output for every legal path. Start from safe defaults, then override for particular operations. This makes omitted paths visible and reduces accidental storage. Defaults must match the specification: defaulting y to zero is wrong if the contract calls for an error flag or an explicit invalid-operation result. always_comb expresses intent and adds language checks; it does not repair an incomplete truth table.\n\nKeep combinational dataflow acyclic. A variable read and written in one block can conceal ordering dependencies, especially when refactoring. Write intermediate expressions in dependency order or use explicit continuous expressions. Compare a small function exhaustively before optimizing its representation.',
 [{title:'Repair an enabled mux without changing its contract',steps:['Specification: enable=0 requires y=0; otherwise select a or b. A process that assigns y only inside if(enable) retains old y while disabled.','Set y=0 before the conditional, then choose a or b when enabled. This covers every binary input combination.','Enumerate enable, select, a and b: sixteen rows. Check disabled rows independently rather than only observing y after a reset.']},{title:'Separate data defaults from error defaults',steps:['For a two-op ALU, legal opcodes are 00 add and 01 XOR. Define illegal opcodes as y=0 and bad_op=1.','Default both signals to those illegal results, then clear bad_op in each legal branch.','A default branch that only writes y leaves bad_op stale; testing all opcode transitions exposes the missing assignment.']}],
 [{prompt:'if(sel) y=a; else z=b; Which outputs can retain values?',hint:'Trace both branches separately for y and z.',answer:'y is unassigned when sel=0; z is unassigned when sel=1. Both need complete assignments or a different, explicitly sequential specification.'},{prompt:'Can an exhaustive binary truth-table test prove absence of glitches?',hint:'Stable function and physical transition behavior differ.',answer:'No. It checks the stable Boolean relation. Propagation delays, hazards and physical timing need separate analysis.'}],['sv-process']),
 'sequential-rtl':d(
 '### Write a next-state recurrence first\nSequential behavior is a relation between pre-edge state, sampled inputs and post-edge state. Express priority in that order: reset, then enable, then hold, if that is the actual contract. A synchronous reset acts only at the active edge; an asynchronous reset also changes state on its assertion event. Deassertion and physical recovery/removal are separate implementation concerns. Simulation alone does not prove safe reset release.\n\nWidth and arithmetic policy belong in the recurrence. An n-bit wrapping counter uses modulo 2^n; a saturating counter holds at its maximum. Distinguish a pulse computed from old state from a flag computed from the new state. Both may be reasonable but they trigger at different observations.',
 [{title:'Reset, enable and wrap priority',steps:['Take a 3-bit counter at q=7. Rule: reset wins, else increment if enable, else hold.','With reset=0 and enable=1, q becomes 0 by modulo-eight arithmetic. With enable=0 it remains 7.','With reset=1 and enable=1, q becomes the reset value, not 0 by an increment calculation. Test the priority explicitly.']},{title:'One-cycle edge detector',steps:['Remember prev from the preceding sampled input. Define rise from current sampled input AND NOT prev.','For sampled input 0,1,1,0,1, the expected pulse sequence is 0,1,0,0,1 when initial prev=0.','If the output pulse is registered, document that those values appear after the corresponding edges. Reset must initialize prev so the first post-reset input has a defined meaning.']}],
 [{prompt:'A saturating 3-bit counter is at 6 with enable high for three edges. Predict its states.',hint:'At the maximum it holds.',answer:'7,7,7. A wrapping implementation would produce 7,0,1 and violates the saturation contract.'},{prompt:'A synchronous reset pulses entirely between clock edges. Must q clear?',hint:'What events execute the process?',answer:'No. If reset is never sampled active at a clock edge, a synchronous-reset process does not clear q. An asynchronous reset has different behavior.'}],['hdl-clock']),
 'fsm-implementation':d(
 '### Translate the table without changing the sampling contract\nUse a state register, combinational next-state logic and explicit output logic. An enumerated state type improves readability; the state encoding remains an implementation choice. Default next_state to state for intentional holds or to a recovery state if the specification demands recovery. Then write every legal table row. Illegal-state recovery is useful defense but does not prove resilience to real hardware faults.\n\nThe 1011 lesson uses a Mealy match derived from state==S101 and the current input. Registering that expression changes when observers can see it. Preserve the written contract when moving logic between combinational and sequential blocks. Match width, reset behavior and overlap policy must remain visible in the testbench.',
 [{title:'Turn one table row into RTL obligations',steps:['S101 with input=0 must go to S10 and not match. With input=1 it must go to S1 and match.','Implement both branches and choose output defaults before the case statement.','Assert reset from each state in separate tests. It must erase prefix history and suppress any stale detection.']},{title:'Cross-check without cloning the state machine',steps:['The DUT uses four prefix states. Let the checker instead track the most recent four valid sampled bits and a valid-count.','After four samples, compare the window with binary 1011. Clear window validity at reset.','Trace 1011011 and compare detections at bit 4 and 7. A checker copied from the DUT transition table could repeat its fallback bug.']}],
 [{prompt:'What two independent tests distinguish S101→S0 from the correct S101→S10 fallback on 0?',hint:'Continue the partial stream after 1010.',answer:'The prefix 1010 followed by 11 should match at the sixth bit; resetting to S0 misses it. Also directly inspect a trace reaching S101 and consuming 0 against the table.'},{prompt:'Does one-hot encoding eliminate the need for default assignments?',hint:'Encoding and path coverage are separate.',answer:'No. Output and next-state assignments still need a defined value for every relevant execution path.'}],['mit-fsm'],55),
 'testbench-development':d(
 '### Build the smallest closed checking loop\nA useful testbench has stimulus, an observation rule, an independent expectation and a failure condition. Add a bounded timeout so missing behavior cannot hang forever. Define test completion as all intended operations issued, all expected results consumed and no pending errors. A final print statement is not a correctness check.\n\nTest the checker itself. Deliberately corrupt one expected value, omit one output or duplicate a transaction in a local experiment. The checker must fail for the intended reason. Keep these mutation runs separate from real passing results and record their commands. Waveforms are diagnostic evidence; automated comparisons make the result repeatable.',
 [{title:'Self-check a four-bit counter',steps:['Reset to zero and sample the settled output. Predict one increment per accepted enable edge using a small integer model masked to four bits.','Include disabled edges, wrap at 15 and reset while enabled. Count each comparison and report its cycle and expected/actual value on failure.','Bound the run, and fail if fewer checks occur than planned. An empty test must not report success.']},{title:'Catch a missing UART byte',steps:['Queue three expected bytes. A passive monitor produces only two observed bytes.','A scoreboard that only compares arrivals sees two correct matches and no mismatch. At end of test, the remaining queue entry proves a missing result.','Add a receive deadline and a final pending-count check. Also reject a fourth unexpected byte rather than ignoring it.']}],
 [{prompt:'The simulator exits with code zero but executes zero comparisons. Is the test acceptable?',hint:'Separate process success from checking success.',answer:'No. Require a minimum planned observation count or explicit completed scenario record, plus no outstanding expected results.'},{prompt:'Where should a monitor get a transmitted payload: the driver object or DUT pins?',hint:'Could a driver bug make those disagree?',answer:'From the observed protocol pins at the documented sampling event. Driver intent can seed expectations, but does not prove that the transfer occurred.'}],['va-architecture']),
 'simulation-debugging':d(
 '### Find the first divergence\nPreserve the failing command, seed, tool version and source revision before editing anything. Minimize the trace around the first incorrect observation, not the final cascade of mismatches. Separate four possibilities: stimulus violates the contract, observation is sampled at the wrong time, the model is wrong, or RTL is wrong. Each requires different evidence.\n\nUnknown values should remain visible until their source is understood. A two-state conversion can make an uninitialized bus look like legal zero. Record reset completion and use a check that rejects unknown control/data where the contract requires a binary value. A clean waveform from one seed is a debugging artifact, not broad regression evidence.',
 [{title:'Diagnose an apparent one-cycle latency bug',steps:['At cycle 12, the checker expects new q but reads old q immediately after the clock event. Inspect whether the DUT uses NBA assignments.','Move the observation to the documented settled phase without changing the expected cycle. If the mismatch disappears, preserve a regression proving the sampling rule.','If the value still lags after settling, inspect the written latency contract and pipeline stages before modifying the DUT.']},{title:'Reduce a random FIFO failure',steps:['Save seed 417 and the complete accepted-operation trace. Identify the first bad output at cycle 83.','Replay only the operations needed to reach that occupancy, then keep the full/empty transition and simultaneous operation that triggers the issue.','Check that the reduced test still fails on the old implementation and passes on the fix; retain the original seed in regression too.']}],
 [{prompt:'Why can fixing the last mismatch in a waveform hide the real bug?',hint:'One corrupt item can shift the whole queue comparison.',answer:'Later mismatches may be consequences of a single earlier insertion, deletion or ordering error. Locate the first divergence between contract, model and observed behavior.'},{prompt:'A test passes after replacing logic with bit in the monitor. What should you investigate?',hint:'Which values does bit discard?',answer:'The conversion may hide X/Z as binary values. Inspect initialization and reset, and retain four-state observations until validity has been established.'}],['cocotb-timing']),
 'verification-planning':d(
 '### A requirement needs both activation and checking\nFor each requirement, record its trigger, legal operating conditions, expected observation, checker and evidence. A test can activate behavior without checking it; coverage can report that activation while a broken output escapes. Conversely, an assertion can be permanently idle if its antecedent never occurs. Plan the stimulus and the observation together.\n\nSeparate legal traffic, negative tests and excluded behavior. A deliberate protocol violation should have a named expected response or an explicitly unspecified outcome. Do not claim a DUT defect merely because an undefined input sequence produced an inconvenient result. Revisit the matrix whenever the contract changes.',
 [{title:'Plan a four-deep FIFO boundary',steps:['Requirement: when full and no accepted read occurs, a write is rejected without changing stored order.','Reach occupancy four using accepted writes; request one extra write; then drain and compare exactly the original four values.','Checker: queue/order plus occupancy invariant. Coverage: full-reject bin. Evidence: trace showing full, request, rejection and unchanged data order.']},{title:'Plan APB wait-state stability',steps:['Requirement: request fields stay stable while an access is waiting. Select one APB revision and signal set.','Generate two wait cycles, then completion. Observe setup, each wait edge and the completion edge.','Use a temporal stability checker and a completion monitor. Add reset-during-wait as a separate requirement with its own cancellation rule.']}],
 [{prompt:'A coverpoint for every address is 100%, but returned data is never checked. What is missing?',hint:'Activation does not compare results.',answer:'A register/data predictor and output comparison linked to each read requirement. Address coverage alone only shows where traffic went.'},{prompt:'How should an unreachable coverage bin be closed?',hint:'Require a reason another engineer can review.',answer:'Demonstrate why it is impossible under the pinned specification/configuration, retain the evidence and an explicit exclusion. Do not silently delete a hard bin to raise the percentage.'}],['ot-methodology','va-coverage']),
 'systemverilog-basics':d(
 '### Choose types for the behavior being observed\nPacked vectors describe contiguous bit fields; unpacked arrays collect separate elements. logic preserves four-state values, while bit cannot represent X/Z. Prefer named typedefs and enums where they express a protocol role, but still specify widths and signedness at arithmetic boundaries. A cast changes interpretation or representation; it is not proof that the original value was valid.\n\nA transaction-oriented testbench often mixes synthesizable signal types with dynamic arrays, queues and classes. Decide which code is a hardware implementation and which runs only in simulation. Tool support varies for classes, constraints, SVA and coverage; record the simulator and supported feature subset rather than assuming every online runner supports them.',
 [{title:'Packed byte versus an array of bits',steps:['logic [7:0] payload is one packed eight-bit value. logic flags[8] is an unpacked collection of eight single-bit values.','For payload=8\'h80, ask whether a later expression interprets it as unsigned 128 or signed −128. Declare the intended interpretation explicitly.','Apply the same vectors to the predictor and DUT interface, including 0x00, 0x7f, 0x80 and 0xff.']},{title:'Preserve unknown reset evidence',steps:['A four-state bus reads 8\'hxx before initialization. A monitor that immediately stores it in bit [7:0] loses that evidence.','First check that the bus is known when a valid transfer is accepted. Only then convert it for a binary reference model.','Keep the reset/valid qualification explicit so expected startup unknowns do not create meaningless errors.']}],
 [{prompt:'Does declaring a signal logic mean multiple procedural drivers are safe?',hint:'Data type does not define ownership.',answer:'No. Assign a clear owner and obey driver restrictions. logic is not a replacement for an intentional resolved net or a multiple-driver design.'},{prompt:'Why should an online exercise that uses only basic RTL not certify SVA or UVM support?',hint:'Different language features need different tool capabilities.',answer:'Compiling one subset says nothing about class libraries, constrained randomization, temporal operators or coverage. Verify those capabilities separately with the chosen tool.'}],['cv-class','cv-interface']),
 'systemverilog-oop':d(
 '### A handle is an identity, not a value copy\nDeclaring a class handle does not allocate an object; new constructs it. Assigning one handle to another makes aliases to the same object. This matters when a monitor reuses a transaction after publishing it: subscribers can accidentally watch previously recorded values change. Define ownership at every boundary and make a deliberate copy when retaining a mutable object. Nested object fields need their own deep-copy policy.\n\nInheritance expresses substitutability. A base handle may refer to a derived object; virtual methods dispatch according to the actual object. An inherited nonvirtual method does not provide the same polymorphic behavior. Use composition when a component simply owns a helper, such as a scoreboard owning a queue, rather than inventing an is-a relationship.',
 [{title:'Find a scoreboard alias bug',steps:['Create packet a with data=0x12, then assign b=a and store b in a history queue. There is still only one packet object.','Change a.data to 0x34 for the next transaction. The history now appears to contain 0x34 too.','Allocate a new packet for every published observation or clone/copy before retention. Verify nested payload arrays and child handles according to their actual copy semantics.']},{title:'Reason about virtual dispatch',steps:['Let Base define virtual function string kind() returning base. Derived extends Base and overrides kind() to return derived.','Construct a Derived object and assign it to a Base handle. Calling kind() through the Base handle invokes the derived implementation.','Repeat with kind() nonvirtual: static handle type determines the method. Write the predicted outputs before running the experiment.']}],
 [{prompt:'You push the same handle into a queue three times, changing its data each time. How many distinct objects are stored?',hint:'Count allocations, not queue entries.',answer:'Three entries refer to one object if new was called only once. All entries see its latest mutable fields.'},{prompt:'Should ErrorPacket extend Packet or should Scoreboard extend Packet?',hint:'Test the is-a relationship.',answer:'ErrorPacket can be a Packet with specialized behavior. A Scoreboard is not a Packet; it should own/consume packets through composition.'}],['cv-class','cv-inheritance','va-architecture'],60),
 'interfaces-modports':d(
 '### Bundle signals, then define ownership and time\nAn interface groups protocol signals. A modport describes a participant’s permitted view and directions; a DUT output is a monitor input. A virtual interface is a handle used by class-based verification code to access an existing interface instance. It does not instantiate another physical interface. Check that it is assigned before use.\n\nA clocking block adds a timing policy for sampling and driving. Its skew and event determine which value a component sees. A monitor using pre-edge sampled inputs should not silently compare them to a post-NBA output contract. Draw a timing line and label sampled request, driven response and settled DUT outputs before selecting skews.',
 [{title:'Assign a ready/valid interface',steps:['Source owns valid and data; sink owns ready; both observe clock/reset. Define transfer only on a sampled edge where valid and ready are high.','The passive monitor owns no protocol outputs. Its modport gives it input views of valid, ready and data.','Hold valid/data while stalled according to the chosen contract. A change during valid && !ready is a protocol violation even if a later transfer has correct data.']},{title:'Pass an instance into a class',steps:['Instantiate bus_if in the module testbench and connect the DUT to it.','Give the driver a virtual bus_if handle through a constructor/configuration mechanism, then validate that it is non-null.','Two drivers pointing to the same interface can contend even though they are different objects. Keep ownership in the environment configuration.']}],
 [{prompt:'Can a monitor determine acceptance from valid alone?',hint:'What happens during backpressure?',answer:'No. For this contract acceptance is sampled valid && ready. Counting valid-only cycles duplicates stalled transactions.'},{prompt:'Does assigning a virtual interface handle create another bus instance?',hint:'It is a reference.',answer:'No. It gives class code access to an existing instance. Elaborate the actual interface in the module hierarchy.'}],['cv-interface','va-architecture']),
 'tasks-functions':d(
 '### Separate pure prediction from timed behavior\nA function must not consume simulation time. Use it for calculations, classification and expected-value prediction. A task may wait on clock events or other timing controls, so it fits bus driving and bounded handshakes. Keep a pure model independent of simulator timing wherever possible; this makes it easier to unit-check and compare with a second model.\n\nLifetime is separate from task/function syntax. Automatic storage gives each invocation its own local state; static storage can be shared across calls. Parallel testbench threads require an intentional policy for local variables and shared queues. No lifetime keyword can make unsynchronized shared mutable state safe by itself.',
 [{title:'Split a bus write into model and driver',steps:['Write a pure merge_bytes(old,data,mask) function that returns the predicted register value. Test masks 0, all bits and single lanes without a clock.','Write a timed write_transfer task that drives setup, holds access through waits and returns only after acceptance or timeout.','Update the register model only after the task/monitor confirms completion. Calling the predictor at setup would commit an operation that may later be reset or rejected.']},{title:'Two overlapping timed calls',steps:['Two caller threads start a helper that keeps an index and waits between bytes. Shared static locals can overwrite each other’s progress.','Give each invocation automatic locals and distinct transaction data. Then serialize actual ownership of the common bus.','Per-call locals prevent local corruption; arbitration prevents the two correct local streams from driving conflicting signals.']}],
 [{prompt:'Should an expected parity calculation be a task that waits for a clock?',hint:'Prediction need not drive time.',answer:'Use a pure function over the sampled data. Let a separate timed monitor decide when that data is valid.'},{prompt:'Why is a forever wait for ready an incomplete driver?',hint:'How does a broken DUT terminate the test?',answer:'It can hang indefinitely. Add a bounded timeout with a clear error and preserve the waiting transaction in failure evidence.'}],['cv-interface']),
 'transaction-verification':d(
 '### Distinguish intent, acceptance and completion\nA transaction represents a protocol operation, not every clock tick. Define the start, accepted payload and terminal event. A requested write may stall, abort at reset or complete with an error. The model must update at the specified event and distinguish unsuccessful completion from success. Include identifiers when multiple operations can be outstanding.\n\nTransaction abstraction should preserve what checkers need. Dropping error status, byte mask or response order can make a neat object unable to reveal a real protocol bug. Conversely, keep pin timing in the driver/monitor instead of filling high-level sequences with cycle-by-cycle assignments.',
 [{title:'Reconstruct one waiting APB access',steps:['Observe setup with PSEL=1,PENABLE=0; capture the request under the protocol contract.','During access PSEL=1,PENABLE=1,PREADY=0, check stable request fields but do not publish completed writes.','At PREADY=1 on the access edge, publish exactly one completion with address, direction, data and error. Reset before that edge cancels the pending operation according to the selected reset contract.']},{title:'Track out-of-order results',steps:['Issue IDs 3 and 4. If the protocol permits responses in either order, a plain FIFO expected queue is insufficient.','Store expected records keyed by ID and reject unknown or duplicate responses. Remove a key only after comparison.','At test end, outstanding keys prove missing responses. If IDs can be reused, define when reuse is legal.']}],
 [{prompt:'Why does a driver log saying write started not justify updating a register model?',hint:'The operation may never complete.',answer:'It records intent. The accepted/completed event, plus success/error policy, determines whether the architectural model changes.'},{prompt:'When is a simple expected FIFO queue appropriate?',hint:'Look at the response ordering contract.',answer:'When completions preserve the modeled operation order. Reordering protocols need IDs or another unambiguous matching rule.'}],['va-architecture','va-scoreboards']),
 'drivers-monitors':d(
 '### Keep stimulus and evidence independent\nThe driver converts an operation into legal pin activity and handles waits, completion and cancellation. The monitor reconstructs operations from observed pins; it must not assume the driver succeeded. Both need the same published interface contract, but their implementations should not share hidden completion decisions. A passive agent can monitor an interface driven by a different environment.\n\nReset is a protocol event. A driver should release outputs into specified idle values and cancel or retry its pending item under an explicit policy. A monitor should discard incomplete frames when required, clear its parsing state and avoid publishing a half-transaction as a completed transfer.',
 [{title:'Backpressure without duplicate transactions',steps:['Drive valid=1 with payload A for three edges; ready is 0,0,1.','Keep the payload stable through the stalled edges. The monitor publishes A only at the third edge.','A valid-only monitor emits three items; an intent-only monitor may emit one before the DUT ever accepts it. Both are wrong for this contract.']},{title:'Abort an APB transfer on reset',steps:['The driver is waiting for PREADY when reset asserts. Its task must terminate/cancel in a bounded way and drive the reset-idle request state.','The monitor drops the unfinished access and waits for a legal post-reset setup.','Record cancellation separately from successful completion. The scoreboard flush policy must match the same reset boundary.']}],
 [{prompt:'A driver and monitor share the same mutable item handle. What two faults can that hide?',hint:'Consider observed values and later edits.',answer:'The monitor may report driver intent instead of pins, and later driver mutation can rewrite retained observations. Reconstruct and publish independently owned data.'},{prompt:'Why use a passive monitor in integration?',hint:'Another component may own stimulus.',answer:'It can check real traffic without taking bus ownership, allowing the same analysis logic to be reused above block level.'}],['va-connection','va-architecture']),
 'scoreboards':d(
 '### Compare only accepted behavior\nSeparate predictor state from output matching. The predictor consumes accepted input transactions and computes expected outputs from the specification. The matcher aligns those outputs with observed completions under the latency/order contract. Define behavior for early, late, extra, missing and unknown results. A mismatch count alone misses an expected queue that never drains.\n\nReset and cancellation must also update predictor state. If reset flushes the DUT, flush the corresponding outstanding expectations and record why they were canceled. If state is retained, do not erase the model merely to avoid mismatches. Avoid reading internal DUT storage to build expectations: it makes the checker agree with the implementation being tested.',
 [{title:'Four-deep FIFO at full occupancy',steps:['The model queue contains A,B,C,D. Request a write E with no accepted read while full. The contract rejects E.','Leave the model queue unchanged; drain and expect A,B,C,D. A request-count model would wrongly predict five items.','For simultaneous read/write while full, apply the explicitly chosen acceptance rule using pre-edge occupancy; do not let sequential Python updates accidentally decide the policy.']},{title:'Detect missing and extra outputs',steps:['Expected outputs are [7,9]. Observations [7] contain no value mismatch, but one pending expected item proves incompletion.','Observations [7,9,9] include an unexpected third output; fail immediately instead of popping an empty queue or ignoring it.','Bound pending latency where required and assert zero pending records at the legitimate end-of-test drain point.']}],
 [{prompt:'Can a scoreboard that compares only values on arrival detect all dropped outputs?',hint:'A dropped output never arrives.',answer:'No. Add outstanding-item accounting, timeout/deadline checks and a final empty expectation check.'},{prompt:'When a queue item is an object, what must the scoreboard copy?',hint:'Follow nested mutable references.',answer:'Enough to preserve an immutable snapshot of the observed/predicted transaction. A shallow handle assignment is not a new object; nested mutable fields may need deep copying.'}],['va-scoreboards'],55),
 'assertions':d(
 '### Translate time in sampled clock ticks\nWrite a timing sentence before SVA: if request is sampled at edge k, acknowledge must be sampled at k+1, for example. req |=> ack checks the consequent starting one sample later; req |-> ack begins at the same sample for a single-cycle antecedent. For a multi-cycle antecedent, alignment is relative to its endpoint. Concurrent assertions use sampled values; a post-NBA signal change is not retroactively visible in the same sampled tick.\n\nUse disable iff for the intended reset abort policy and understand its asynchronous disabling semantics. A false antecedent can make an implication pass vacuously, so add coverage for the triggering scenario. Track attempts and meaningful successes; a property with no activation is not useful evidence of a response.',
 [{title:'One-cycle response, passing and failing traces',steps:['Contract: every sampled req=1 requires ack=1 at the next edge; reset disables the obligation. Property shape: @(posedge clk) disable iff(!rst_n) req |=> ack.','At edges k,k+1,k+2, req=[1,0,0] and ack=[0,1,0] satisfy the obligation started at k. ack=[1,0,0] does not; same-cycle acknowledge cannot satisfy the specified next-cycle check.','If req stays zero for the entire run, implication success may be vacuous. Add a cover property for req followed by next-cycle ack and inspect trigger counts.']},{title:'Hold data through a stalled transfer',steps:['Contract: valid && !ready at edge k means valid and data remain stable at k+1, including an edge where ready rises.','Use the shape (valid && !ready) |=> (valid && $stable(data)), with the appropriate reset qualification.','Trace valid=[1,1,1], ready=[0,0,1]. All three sampled payloads must agree. Add a separate known-value check where X data is forbidden.']}],
 [{prompt:'req=[0,1,0], ack=[0,1,0]. Does req |=> ack pass its triggered obligation?',hint:'Index the edge after req.',answer:'No. The req at the middle edge requires ack at the final edge, which is zero. Same-cycle ack would be relevant to an overlapping single-cycle implication.'},{prompt:'Your response assertion never fails across 100 seeds; its antecedent coverage is zero. What can you claim?',hint:'No activation means no response was tested.',answer:'Only that no checked obligation failed under those runs. Fix stimulus or qualification so requests occur, inspect nonvacuous attempts and retain a deliberately failing checker test.'}],['cv-sva'],65),
 'functional-coverage':d(
 '### Define bins from requirements, not convenient signals\nFunctional coverage measures whether named scenarios were observed. Choose an event that corresponds to accepted behavior; sampling a generated item before acceptance inflates evidence. For a FIFO, occupancy-before-operation and accepted operation are useful dimensions. For a bus, address, direction, wait count and completion status may be useful. Each cross should answer a planned verification question.\n\nA bin hit does not compare data, ordering or timing. Pair activation coverage with independent checking. ignore_bins documents irrelevant combinations; illegal_bins flags sampled forbidden combinations but is not a substitute for all protocol assertions. Keep exclusions reviewable and configuration-specific. Huge automatic crosses create noise and can conceal meaningful holes.',
 [{title:'Boundary coverage for a depth-four FIFO',steps:['Define pre-operation occupancy bins empty=0, middle=1..3, full=4. Classify accepted read/write and rejected requests separately.','An attempted write at full must hit the full-reject scenario, not accepted-write coverage. Sample after acceptance decisions are known while retaining pre-edge occupancy.','Cross only meaningful occupancy/operation cases. Review impossible combinations against the acceptance contract rather than inventing illegal traffic to hit them.']},{title:'APB wait coverage with a data bug',steps:['Create bins for zero, one and multiple wait cycles at completed transfers. Run one transfer in every bin.','Coverage can reach 100% while a DUT returns the wrong data on every read. The scoreboard must compare data/error independently.','Add a requirement matrix linking these bins to stability assertions and register-model comparisons. Track failures alongside the coverage result.']}],
 [{prompt:'Should repeated stalled cycles count as repeated accepted transactions?',hint:'Name the sampling event.',answer:'No. Sample acceptance/completion once per transaction, or explicitly create a separate wait-duration metric.'},{prompt:'100% functional coverage and a failing scoreboard occur in one run. Is verification complete?',hint:'Coverage and correctness answer different questions.',answer:'No. The planned scenarios were activated, but the behavior failed checking. Fix or explain failures and rerun reproducibly.'}],['cv-coverage','va-coverage'],60),
 'constrained-random':d(
 '### Legality and exploration are different jobs\nConstraints describe allowed stimulus; they are not a checklist of scenarios already tested. Check every randomize() return value. A failed solve must stop or trigger an explicit recovery policy, not send a stale item that merely looks randomized. Keep hard protocol legality separate from test-specific bias so a corner-case test can target rare legal behavior without weakening the interface contract.\n\nRecord the seed, configuration, source revision and tool version. A seed alone is not a portable guarantee across changed code or solvers. Biasing values improves exploration but cannot promise finite-run coverage. Start with directed boundary tests, then use random traffic plus coverage feedback to explore combinations and ordering.',
 [{title:'Unsatisfiable length constraints',steps:['A packet has hard length inside 1..8. A particular test adds inline length==0. No legal solution exists.','If randomize returns false, report the conflict and fail that generation attempt. Do not drive the previous packet values.','For a legal zero-length negative test, use a separately specified invalid-traffic path with an expected rejection/checking policy, not a hidden contradiction in legal generation.']},{title:'Reach a rare FIFO boundary deliberately',steps:['Unbiased read/write choices may hover near the middle and rarely hit full. Directed fill first establishes the full boundary.','Then randomize bursts and backpressure while tracking occupancy/operation coverage. Keep the model based on accepted operations.','When a bin remains unhit, inspect constraints and reachability before simply adding seeds. Preserve a minimized failing trace alongside the seed.']}],
 [{prompt:'A constraint permits values 0..15. Do sixteen random samples guarantee every value?',hint:'Sampling can repeat.',answer:'No. rand-style sampling can repeat and distribution does not guarantee full finite-run coverage. Use a directed sweep or an appropriate cyclic policy where suitable, and measure actual hits.'},{prompt:'Why does a randomize failure followed by normal driving create misleading evidence?',hint:'The item may retain old data.',answer:'The test can silently reuse stale values while reporting a new randomized operation. Check the result and make failure explicit before sending the item.'}],['cv-random','cv-constraints'],60),
 'uvm-introduction':d(
 '### Map responsibilities before adding the framework\nUVM standardizes reusable verification structure. A sequence describes transaction intent, a sequencer arbitrates requests, a driver performs protocol timing and a monitor publishes observed traffic. Predictors, scoreboards and coverage consumers analyze those observations. The framework does not decide whether the specification or model is correct. Build one small checked transfer before adding factories, virtual sequences or register layers.\n\nComponents have a hierarchy and phase lifecycle; transactions and sequences are objects with different lifetimes. Build creates/configures components, connect wires communication paths and run performs time-consuming activity. Test completion needs a deliberate objection and drain policy so the run neither ends early nor hangs after traffic stops.',
 [{title:'Trace a single APB write through the environment',steps:['The sequence creates one write item. The sequencer grants it to the driver.','The driver requests the item, drives setup/access, waits for completion or timeout, and signals item_done under its chosen completion contract.','The monitor independently publishes completion. The predictor updates the register model and the scoreboard checks observed behavior. Calling item_done is not itself proof that the DUT stored the data.']},{title:'End a test with pending reads',steps:['The last stimulus sequence finishes while two expected read responses remain. Dropping the final objection immediately can terminate checking too soon.','Wait for a bounded drain condition: no pending expectations and all required protocol completions observed.','If the drain deadline expires, fail with outstanding IDs and recent trace. Do not hold an objection forever while waiting for a broken DUT.']}],
 [{prompt:'Does replacing a plain SV testbench with UVM automatically improve its oracle?',hint:'Structure cannot repair a wrong expected value.',answer:'No. The model still needs independent specification-based reasoning, boundary vectors and checker validation.'},{prompt:'Which component should own pin timing: sequence or driver?',hint:'Keep intent reusable across interfaces.',answer:'The driver. Sequences express operations and policies; the driver implements the protocol timing and completion semantics.'}],['va-architecture','va-connection'],55),
 'uvm-components':d(
 '### Connect a complete observation path\nCreate the component hierarchy before connecting its communication endpoints. An active agent includes stimulus-driving machinery and monitoring; a passive configuration retains monitoring without driving. Analysis communication broadcasts observations to consumers. When a consumer retains an item, define a snapshot/copy convention because broadcasting a handle does not freeze its object.\n\nThe get_next_item/item_done handshake coordinates sequencer and driver. Complete each acquired request exactly once under the chosen driver use model. A reset or timeout path needs an explicit completion/cancellation policy too. Analysis write methods must not consume time; use a queue or analysis FIFO when later timed processing is required.',
 [{title:'Connect monitor to checker and coverage',steps:['Build one monitor, scoreboard and coverage subscriber. In connect, attach the monitor analysis port to both consumers.','Publish an independently reconstructed transaction after completion. Coverage samples the accepted scenario; the scoreboard compares expected behavior.','If either consumer queues the object, clone/copy it or require immutable publication. A reused mutable handle can corrupt both histories.']},{title:'Debug a sequence that never returns',steps:['The driver calls get_next_item and drives the bus, but forgets item_done on an error branch.','The sequencer still sees an outstanding request, so the sequence may block even though pin traffic has stopped.','Instrument acquisition/completion pairs, add bounded waits and handle all success/reset/timeout paths consistently. Preserve the protocol failure rather than reporting success just to unblock.']}],
 [{prompt:'What should change when reusing an agent as passive?',hint:'It observes traffic owned elsewhere.',answer:'Disable driver/sequencer creation or activation according to configuration, retain the monitor and analysis connections, and ensure it owns no DUT-driving outputs.'},{prompt:'Can a subscriber sleep inside analysis write to wait for another transaction?',hint:'write is a function-style callback.',answer:'No timed wait belongs there. Enqueue a snapshot and perform timed/blocking processing in a task via an appropriate FIFO/queue mechanism.'}],['va-connection','va-scoreboards'],55),
 'coverage-closure':d(
 '### Classify holes before choosing an action\nA missing bin can mean absent stimulus, overconstraint, a sampling bug, an unreachable scenario or a DUT failure preventing progress. Each category has a different remedy. Inspect the requirement and an actual trace before biasing random generation. Keep a closure log with the hole, hypothesis, experiment, evidence and resolution.\n\nMerge coverage only across compatible design, model, configuration and tool versions. A percentage from incompatible databases can look complete while describing no real executable configuration. Closure also requires reviewing failures, assertion activation, pending scoreboard items and exclusions. Record residual risk rather than hiding it behind one aggregate number.',
 [{title:'Close a missing full-plus-read/write scenario',steps:['Confirm the FIFO policy permits simultaneous operations at full. Inspect whether the generator incorrectly forbids writes whenever full, even when an accepted read frees space under that policy.','Write a directed fill-then-simultaneous test and inspect the monitor event. If the checker passes but the bin stays empty, fix sampling/classification.','If the policy forbids the combination, retain a requirement-linked exclusion instead of changing stimulus to violate the contract.']},{title:'Reject an incompatible merge',steps:['Regression A tests depth 4; regression B tests depth 16 with a different occupancy model.','Do not present their union as 100% coverage of one configuration. Report each configuration and map requirements deliberately.','Pin source and coverage model revisions in the report, with actual failing tests and documented exclusions.']}],
 [{prompt:'What evidence distinguishes unreachable from merely unobserved?',hint:'A finite run with no hits is insufficient.',answer:'A specification/configuration argument, constraint analysis or stronger reachability proof. Absence in random runs alone does not establish impossibility.'},{prompt:'Why rerun directed tests after fixing a coverage sampling bug?',hint:'Old data was measured incorrectly.',answer:'The previous hit/miss record is unreliable. Recollect coverage with the corrected model and revalidate its relation to accepted behavior.'}],['va-coverage','ot-methodology']),
 'fifo-verification':d(
 '### Specify the boundary acceptance matrix\nFor a synchronous FIFO, define depth, reset contents/validity, read latency and simultaneous-operation behavior before writing a queue model. Full and empty decisions usually reference pre-edge occupancy, but some designs allow a full write when a simultaneous read succeeds. That is a contract choice. Never let the order of queue push/pop statements silently choose it.\n\nMaintain invariants independently: occupancy stays in 0..depth, output order follows accepted writes minus accepted reads, and rejected requests do not alter architectural contents. Pointer wrap is an implementation detail that still needs stress through enough operations. An asynchronous FIFO adds cross-domain flag latency and CDC concerns outside this synchronous model.',
 [{title:'Full simultaneous read/write with exchange allowed',steps:['Depth=2 and model queue=[A,B]. Contract explicitly allows both read and write at full if read is accepted. Request read plus write C.','Using pre-edge occupancy and the policy, accept both operations. The read result is A and the next queue is [B,C].','If the chosen design instead rejects full writes regardless of read, the correct next queue would be [B]. Test and document exactly one policy, not an accidental mixture.']},{title:'Reset a nonempty queue',steps:['Fill with A,B and reset before either is read. A flush-reset contract makes the model empty.','A subsequent read request must follow empty behavior, not return A as a valid result.','Test reset during pending registered reads separately: define whether an already accepted response is canceled or must complete.']}],
 [{prompt:'Depth=3, occupancy=0, simultaneous read/write with no bypass. What is read acceptance?',hint:'Use pre-edge empty and the no-bypass rule.',answer:'Reject the read and accept the write if otherwise legal. Next occupancy is 1; the newly written value is not an immediate valid read response.'},{prompt:'Why are depth+1 writes insufficient to prove pointer wrap ordering?',hint:'Full rejection may prevent any wrap.',answer:'A full FIFO can reject further writes without advancing pointers. Interleave accepted reads/writes for multiple complete wraps and compare the queue order.'}],['va-scoreboards'],55),
 'apb-verification':d(
 '### Separate setup, access and completion\nAPB setup has selected peripheral and PENABLE low. Access raises PENABLE; it can persist for wait states until PREADY completes the transfer. The selected APB revision determines optional signals such as errors and byte strobes. Pin that revision and the peripheral register map before claiming compliance. Model a successful write at completion, not setup; a reset-aborted operation is not a completed write.\n\nRegister behavior can be more than ordinary storage. Read-only, write-one-to-clear, reserved bits and side effects each need an explicit predictor. Use independent byte-lane merging for masked writes. Compare responses and errors, then track functional scenarios such as waits, addresses and back-to-back operation separately.',
 [{title:'A two-wait-state write',steps:['Edge 0 observes setup: PSEL=1,PENABLE=0. Edge 1 begins access with PREADY=0; edge 2 is another wait.','Keep address, direction, write data and applicable strobes stable. At edge 3, PREADY=1 completes once.','Only then update the register predictor if the contract says the write succeeds. Count two waiting access edges, not the setup edge.']},{title:'Byte mask and write-one-to-clear',steps:['For ordinary 32-bit storage old=0x11223344, data=0xAABBCCDD, strobe=0101 updates lanes 0 and 2. Expected new value is 0x11BB33DD.','For a write-one-to-clear status bit, writing 1 clears the enabled bit; writing 0 preserves it. Ordinary byte replacement is the wrong predictor.','Use separate requirement rows for each register behavior and prove invalid addresses/errors do not accidentally update unrelated state.']}],
 [{prompt:'Can PENABLE stay high between two distinct back-to-back transfers?',hint:'Each transfer needs setup.',answer:'A new transfer requires a setup phase with PENABLE low. PSEL may remain asserted for the same peripheral under the protocol, but setup/access sequencing still applies.'},{prompt:'Why retain the request during waits rather than reconstructing it only at completion?',hint:'Stability violations can disappear by the final edge.',answer:'The monitor/checker must compare fields across every waiting access edge. Correct final fields do not excuse changes while stalled.'}],['va-architecture'],55),
 'uart-verification':d(
 '### Publish an exact frame and tolerance contract\nChoose data bits, parity, stop bits, bit order, idle polarity, clock/baud relation and reset behavior. For an 8N1 receiver, a legal frame has start low, eight least-significant-bit-first data bits and stop high. Receiver implementations differ in oversampling, false-start filtering and tolerance; derive expected sampling instants from the chosen design contract rather than claiming universal UART tolerance.\n\nA robust checker distinguishes malformed frames, missing bytes, duplicate bytes and correct recovery. The transmitter driver says what it intended to send; the receive-valid/data monitor proves what was observed. Keep every wait bounded and state whether a reset in mid-frame cancels that frame.',
 [{title:'Encode and decode 0xA6 in 8N1',steps:['0xA6 has binary representation 10100110. The transmitted data order is 0,1,1,0,0,1,0,1 after the start bit.','Prepend start=0 and append stop=1. Schedule bit boundaries from the selected baud model, then sample at the specified bit centers.','The independent decoder reconstructs 0xA6 only after a valid stop. A stop-bit error must follow the documented drop/error policy rather than becoming an ordinary valid byte.']},{title:'Recovery after reset and malformed traffic',steps:['Start a frame and reset during its fourth data bit. Under a cancel-on-reset contract, remove that pending expectation.','After reset release, return to idle and send a complete legal frame. Check exactly one valid byte with the correct value.','Run a malformed-stop case followed by a legal frame; bound recovery time and reject extra outputs. A driver log alone cannot prove recovery.']}],
 [{prompt:'Why does testing only 0x00 and 0xFF miss bit-order mistakes?',hint:'Reversing either pattern changes nothing.',answer:'Both are symmetric under reversal. Include asymmetric payloads such as 0xA6, walking bits and boundary timing cases.'},{prompt:'What must be documented before a baud mismatch sweep can be called a pass?',hint:'Tolerance needs an expected boundary.',answer:'The allowed transmitter/receiver mismatch, clock assumptions, sampling policy and expected behavior beyond tolerance. Record actual tested points without claiming a universal standard limit.'}],['uart-ti'],55)
};
Object.assign(studyDepth['systemverilog-oop'],{
 flow:['handle a → object #1','b = a → same object #1','copy/new → object #2'],
 caption:'Handle assignment aliases one object. A deliberate value/deep-copy policy is needed to retain independent history.',
 code:`class Packet;
  bit [7:0] data;
  virtual function string kind(); return "packet"; endfunction
endclass
class ErrorPacket extends Packet;
  function string kind(); return "error"; endfunction
endclass
module alias_demo;
  initial begin
    Packet a, b, snapshot, base;
    ErrorPacket child;
    a = new(); a.data = 8'h12;
    b = a;                   // alias, not copy
    snapshot = new(); snapshot.data = a.data; // scalar snapshot
    a.data = 8'h34;
    assert (b.data == 8'h34 && snapshot.data == 8'h12);
    child = new(); base = child;
    assert (base.kind() == "error");
  end
endmodule`
});
